    for k in tot: print(f"  TOTAL {k}: jobs={n[k]} sec={tot[k]:.0f} min={tot[k]/60:.1f} billed_roundup_min={0}")
    import math
    for k in tot: print('  billed(round-up per job)',k,sum(math.ceil(r[3]/60) for r in rows if r[1]==k))
